import {
  ChangeDetectionStrategy,
  Component,
  input,
  output,
} from "@angular/core";
import { MatButton } from "@angular/material/button";
import { MatCard, MatCardContent } from "@angular/material/card";
import { MatIcon } from "@angular/material/icon";
import { MatProgressSpinner } from "@angular/material/progress-spinner";

/**
 * The AI-written summary panel. The text is generated by the server (the AI service's key never reaches the browser) and
 * fetched by the page that shows the book; this panel shows what it is given and reports the button click.
 */
@Component({
  selector: "app-book-summary",
  templateUrl: "./book-summary.component.html",
  styleUrls: ["./book-summary.component.scss"],
  imports: [MatCard, MatCardContent, MatButton, MatIcon, MatProgressSpinner],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class BookSummaryComponent {
  readonly summary = input("");
  readonly loading = input(false);
  readonly error = input("");
  readonly generate = output<void>();
}
